public class NodeUtil_newQualifiedNameNodeDeclaration_TriageGen2Test {

  private CodingConvention convention;

  @Before
  public void setUp() {
    convention = CompilerTestUtil.makeDummyCodingConvention();
  }

  @Test
  public void testNewQualifiedNameNodeDeclaration_WithNameIsName() {
    // Case 1: nameNode.isName() is true
    // This typically happens with simple identifiers like "x"
    String name = "x";
    Node value = IR.string('y');
    JSDocInfo info = JSDocInfo.blank();

    Node result = NodeUtil.newQualifiedNameNodeDeclaration(convention, name, value, info);

    assertNotNull(result);
    // When isName is true, result = IR.var(nameNode, value)
    // IR.var creates a VAR node where the first child is the name node
    assertEquals(Token.VAR, result.getType());
    assertEquals(name, result.getFirstChild().getString());
    assertEquals(value, result.getSecondChild());
    assertEquals(info, result.getJSDocInfo());
  }

  @Test
  public void testNewQualifiedNameNodeDeclaration_WithNameIsNotName() {
    // Case 2: nameNode.isName() is false
    // This happens with qualified names like "a.b.c"
    // In Rhino, a qualified name node structure is usually a chain of properties
    String name = "a.b.c";
    Node value = IR.string('y');
    JSDocInfo info = JSDocInfo.blank();

    Node result = NodeUtil.newQualifiedNameNodeDeclaration(convention, name, value, info);

    assertNotNull(result);
    // When isName is false, result = IR.exprResult(IR.assign(nameNode, value))
    // IR.exprResult creates an EXPR node
    assertEquals(Token.EXPR, result.getType());

    // The assignment is the first child of the EXPR node
    Node assignNode = result.getFirstChild();
    assertEquals(Token.ASSIGN, assignNode.getType());

    // The JSDoc info should be set on the first child of the result (the assignment node)
    assertEquals(info, assignNode.getJSDocInfo());

    // Verify the assignment targets the qualified name
    assertEquals(name, assignNode.getFirstChild().getString());
    assertEquals(value, assignNode.getSecondChild());
  }

  @Test
  public void testNewQualifiedNameNodeDeclaration_NullInfo() {
    // Testing with null JSDocInfo to ensure no NullPointerException if the implementation allows
    String name = "x";
    Node value = IR.string('y');

    Node result = NodeUtil.newQualifiedNameNodeDeclaration(convention, name, value, null);

    assertNotNull(result);
    assertEquals(null, result.getJSDocInfo());
  }
}

/**
 * Dummy helper to satisfy the convention requirement if not provided by environment.
 */
class CompilerTestUtil {
  static CodingConvention makeDummyCodingConvention() {
    return new CodingConvention() {
      @Override
      public String getIndent() { return ""; }
      @Override
      public String getJsDocFormatting() { return ""; }
      @Override
      public String getPropertyName() { return ""; }
      @Override
      public String getPropertyNameSeparator() { return ""; }
      @Override
      public String getVarNameSeparator() { return ""; }
      @Override
      public String getCommentStyle() { return ""; }
    };
  }
}
